def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = me[-1]
    last_op = op[-1]

    # In the final round, defection is strictly best regardless of prediction.
    if n >= 99:
        return 'D'

    op_c = 0
    for i in range(n):
        if op[i] == 'C':
            op_c += 1
    op_d = n - op_c

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0
    recent_op_c = 0
    for i in range(recent_start, n):
        if op[i] == 'C':
            recent_op_c += 1

    # Learn opponent responses to our previous move:
    # if our previous action was D, did they next cooperate (forgive) or defect (punish)?
    after_d_c = after_d_d = after_c_c = after_c_d = 0
    recent_after_d_c = recent_after_d_d = recent_after_c_d = 0
    recent_trans_start = n - 12
    if recent_trans_start < 1:
        recent_trans_start = 1

    for i in range(1, n):
        prev_me = me[i - 1]
        curr_op = op[i]
        if prev_me == 'D':
            if curr_op == 'C':
                after_d_c += 1
            else:
                after_d_d += 1
            if i >= recent_trans_start:
                if curr_op == 'C':
                    recent_after_d_c += 1
                else:
                    recent_after_d_d += 1
        else:
            if curr_op == 'C':
                after_c_c += 1
            else:
                after_c_d += 1
                if i >= recent_trans_start:
                    recent_after_c_d += 1

    d_total = after_d_c + after_d_d
    recent_d_total = recent_after_d_c + recent_after_d_d
    if recent_d_total > 0:
        forgiving = recent_after_d_c * 100 // recent_d_total
    elif d_total > 0:
        forgiving = after_d_c * 100 // d_total
    else:
        forgiving = 50

    # Mostly-defective opponent that does not reward our cooperation after D.
    hard_defector = (op_c == 0) or (
        op_c <= n // 4 and recent_after_d_c == 0 and recent_op_c <= 3 and op_d >= 4
    )

    # Opponent's last move is more plausibly retaliation for our action two rounds ago.
    provoked = n >= 2 and me[-2] == 'D'

    # Opponent is mostly defective.
    if op_c <= n // 3:
        if last_op == 'D':
            # If their D likely punished our earlier D, try to de-escalate.
            if provoked and not hard_defector and forgiving >= 40 and recent_after_c_d <= 2:
                return 'C'
            if last_me == 'D':
                if hard_defector:
                    return 'D'
                if forgiving >= 70:
                    return 'C' if rng.random() < 0.60 else 'D'
                return 'C' if rng.random() < 0.50 else 'D'
            return 'D'

        # They just cooperated. If they have shown forgiveness to our D, keep exploiting.
        if last_me == 'D':
            if forgiving >= 60 or recent_after_d_c >= 1:
                if rng.random() < 0.60:
                    return 'D'
            return 'C'
        return 'C'

    # Opponent is very cooperative.
    if op_c >= n - max(1, n // 10):
        if last_op == 'D':
            # Do not keep escalating if their D was provoked and they are still mostly nice.
            if provoked and not hard_defector and recent_after_c_d <= 2:
                return 'C'
            if last_me == 'D':
                if hard_defector or recent_op_c <= 2 or forgiving <= 25:
                    return 'D'
                return 'C'
            return 'D'

        # They just cooperated while we defected. If they usually forgive D, exploit.
        if last_me == 'D':
            if forgiving >= 60 or recent_after_d_c >= 1:
                if rng.random() < 0.75:
                    return 'D'
                return 'C'
            # Controlled late probe, mostly after evidence is impossible.
            if n >= 98 and forgiving == 50 and rng.random() < 0.12:
                return 'D'
            return 'C'

        # Mutual cooperation: limited endgame pressure when likely safe.
        if n >= 90:
            if forgiving >= 70:
                p = 0.55
            elif forgiving >= 55:
                p = 0.30
            elif forgiving == 50:
                p = 0.08 if n >= 97 else 0.01
            else:
                p = 0.03
            if rng.random() < p:
                return 'D'
        return 'C'

    # Mixed behavior regime.
    if last_op == 'D':
        # Avoid turning a provoked punishment into a long mutual-D loop.
        if provoked and not hard_defector and recent_after_c_d <= 2:
            return 'C'

        if last_me == 'D':
            # Mutual D: reset against forgiving/mostly cooperative opponents, stay D vs hard defectors.
            if op_c >= n // 2 and forgiving >= 45 and not hard_defector and recent_op_c > 2:
                return 'C' if rng.random() < 0.60 else 'D'
            if hard_defector:
                return 'D'
            return 'C' if rng.random() < 0.25 else 'D'

        # Opponent defected after our cooperation: punish unless clearly forgiving and isolated.
        if forgiving >= 75 and recent_after_c_d <= 1 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    if last_me == 'D':
        # We exploited last round. Continue only if their pattern shows forgiveness.
        if forgiving >= 65 and op_c >= n // 2:
            if rng.random() < 0.70:
                return 'D'
        elif forgiving == 50 and n >= 97 and rng.random() < 0.10:
            return 'D'
        elif n >= 95 and forgiving >= 40 and op_c >= n - max(1, n // 15):
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    # Mutual cooperation in the mixed regime.
    if n >= 90:
        if forgiving >= 70:
            p = 0.50
        elif forgiving >= 55:
            p = 0.25
        elif forgiving == 50:
            p = 0.06 if n >= 97 else 0.008
        else:
            p = 0.02
        if rng.random() < p:
            return 'D'

    # Rare safe probe against a perfectly cooperative history.
    if op_c == n and n > 80 and forgiving == 50 and rng.random() < 0.005:
        return 'D'

    return 'C'
